function throttle(fn, interval = 200) {
  let last = 0;
  let timer;
  return (...args) => {
    const now = Date.now();
    if (now - last >= interval) {
      last = now;
      fn(...args);
    } else {
      clearTimeout(timer);
      timer = setTimeout(() => {
        last = Date.now();
        fn(...args);
      }, interval - (now - last));
    }
  };
}

