async function fetchMany(urls) {
  const tasks = urls.map(url => fetch(url).then(r => r.json()));
  const results = await Promise.allSettled(tasks);
  const success = [];
  const failed = [];
  results.forEach((r, i) => {
    if (r.status === 'fulfilled') success.push({ url: urls[i], data: r.value });
    else failed.push({ url: urls[i], reason: r.reason });
  });
  return { success, failed };
}

