async function retry(fn, { retries = 3, baseDelay = 300 } = {}) {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (e) {
      attempt++;
      if (attempt > retries) throw e;
      const delay = baseDelay * 2 ** (attempt - 1);
      await new Promise(r => setTimeout(r, delay));
    }
  }
}

