function createBus() {
  const map = new Map();
  return {
    on(event, handler) {
      (map.get(event) || map.set(event, []).get(event)).push(handler);
    },
    off(event, handler) {
      const list = map.get(event);
      if (!list) return;
      const i = list.indexOf(handler);
      if (i >= 0) list.splice(i, 1);
    },
    emit(event, payload) {
      (map.get(event) || []).forEach(h => h(payload));
    }
  };
}

