function createLRU(limit = 50) {
  const map = new Map();
  return {
    get(key) {
      if (!map.has(key)) return undefined;
      const value = map.get(key);
      map.delete(key);
      map.set(key, value);
      return value;
    },
    set(key, value) {
      if (map.has(key)) map.delete(key);
      map.set(key, value);
      if (map.size > limit) {
        const firstKey = map.keys().next().value;
        map.delete(firstKey);
      }
    }
  };
}

