function trackIdle(timeout = 60000, onChange) {
  let timer;
  let idle = false;
  const reset = () => {
    clearTimeout(timer);
    if (idle) {
      idle = false;
      onChange(false);
    }
    timer = setTimeout(() => {
      idle = true;
      onChange(true);
    }, timeout);
  };
  ['mousemove', 'keydown', 'click', 'scroll'].forEach(ev =>
    window.addEventListener(ev, reset, { passive: true })
  );
  reset();
}

