function buildTree(list, { idKey = 'id', parentKey = 'parentId', childrenKey = 'children' } = {}) {
  const map = new Map();
  const roots = [];
  list.forEach(item => {
    map.set(item[idKey], { ...item, [childrenKey]: [] });
  });
  map.forEach(node => {
    if (node[parentKey] == null) {
      roots.push(node);
    } else {
      const parent = map.get(node[parentKey]);
      parent?.[childrenKey].push(node);
    }
  });
  return roots;
}

