function get(obj, path, defaultValue) {
  if (!path) return obj;
  const keys = Array.isArray(path) ? path : String(path).split('.');
  let cur = obj;
  for (const key of keys) {
    if (cur == null || !(key in cur)) return defaultValue;
    cur = cur[key];
  }
  return cur;
}

