function set(obj, path, value) {
  const keys = Array.isArray(path) ? path : String(path).split('.');
  let cur = obj;
  keys.forEach((key, index) => {
    if (index === keys.length - 1) {
      cur[key] = value;
    } else {
      if (typeof cur[key] !== 'object' || cur[key] === null) {
        cur[key] = {};
      }
      cur = cur[key];
    }
  });
  return obj;
}

