class EventEmitter {
  constructor() {
    this._events = new Map();
  }
  on(event, listener) {
    const list = this._events.get(event) || [];
    list.push(listener);
    this._events.set(event, list);
    return this;
  }
  once(event, listener) {
    const wrap = (...args) => {
      this.off(event, wrap);
      listener(...args);
    };
    return this.on(event, wrap);
  }
  off(event, listener) {
    if (!listener) {
      this._events.delete(event);
      return this;
    }
    const list = this._events.get(event) || [];
    this._events.set(event, list.filter(l => l !== listener));
    return this;
  }
  emit(event, ...args) {
    const list = this._events.get(event) || [];
    list.forEach(l => l(...args));
  }
}

