function createAsyncQueue(limit = 3) {
  const queue = [];
  let active = 0;

  const runNext = () => {
    if (active >= limit) return;
    const task = queue.shift();
    if (!task) return;
    active++;
    task().finally(() => {
      active--;
      runNext();
    });
  };

  return function push(taskFn) {
    return new Promise((resolve, reject) => {
      queue.push(() => taskFn().then(resolve, reject));
      runNext();
    });
  };
}

