class ReconnectingWebSocket {
  constructor(url, protocols) {
    this.url = url;
    this.protocols = protocols;
    this.retries = 0;
    this.maxRetries = 5;
    this.listeners = { open: [], message: [], close: [], error: [] };
    this._connect();
  }
  _connect() {
    const ws = new WebSocket(this.url, this.protocols);
    this.ws = ws;
    ws.addEventListener('open', e => {
      this.retries = 0;
      this.listeners.open.forEach(l => l(e));
    });
    ws.addEventListener('message', e => this.listeners.message.forEach(l => l(e)));
    ws.addEventListener('close', e => {
      this.listeners.close.forEach(l => l(e));
      if (this.retries < this.maxRetries) {
        const delay = 1000 * 2 ** this.retries++;
        setTimeout(() => this._connect(), delay);
      }
    });
    ws.addEventListener('error', e => this.listeners.error.forEach(l => l(e)));
  }
  on(type, handler) {
    this.listeners[type]?.push(handler);
  }
  send(data) {
    this.ws?.readyState === WebSocket.OPEN && this.ws.send(data);
  }
}

function connectSSE(url, { onMessage, onError, onOpen } = {}) {
  const es = new EventSource(url);
  es.onopen = (e) => onOpen?.(e);
  es.onerror = (e) => onError?.(e);
  es.onmessage = (e) => {
    try {
      const data = JSON.parse(e.data);
      onMessage?.(data, e);
    } catch {
      onMessage?.(e.data, e);
    }
  };
  return () => es.close();
}

