function createTabChannel(name = 'app-channel') {
  const bc = new BroadcastChannel(name);
  return {
    post(type, payload) {
      bc.postMessage({ type, payload });
    },
    on(type, handler) {
      bc.addEventListener('message', (e) => {
        if (e.data?.type === type) handler(e.data.payload, e);
      });
    },
    close() {
      bc.close();
    }
  };
}

