class Router {
  constructor() {
    this.routes = new Map();
    window.addEventListener('popstate', () => this._render(location.pathname));
  }
  add(path, handler) {
    this.routes.set(path, handler);
  }
  navigate(path) {
    history.pushState(null, '', path);
    this._render(path);
  }
  _render(path) {
    const handler = this.routes.get(path) || this.routes.get('*');
    handler?.(path);
  }
}

