function setupHashTabs() {
  const tabs = document.querySelectorAll('[data-tab]');
  const show = (name) => {
    tabs.forEach(t => {
      t.hidden = t.dataset.tab !== name;
    });
  };
  const applyFromHash = () => {
    const { tab } = getHashParams();
    if (tab) show(tab);
  };
  window.addEventListener('hashchange', applyFromHash);
  applyFromHash();
}

