function sortBy(arr, selector, { desc = false } = {}) {
  const get = typeof selector === 'function' ? selector : (x) => x[selector];
  return [...arr].sort((a, b) => {
    const va = get(a);
    const vb = get(b);
    if (va < vb) return desc ? 1 : -1;
    if (va > vb) return desc ? -1 : 1;
    return 0;
  });
}

