const setUtil = {
  union(a, b) {
    return [...new Set([...a, ...b])];
  },
  intersect(a, b) {
    const s = new Set(b);
    return a.filter(x => s.has(x));
  },
  difference(a, b) {
    const s = new Set(b);
    return a.filter(x => !s.has(x));
  }
};

