}

export function parseArgs(argv = process.argv.slice(2)) {
  const args = {};
  for (const arg of argv) {
    if (arg.startsWith('--')) {
      const [k, v = true] = arg.slice(2).split('=');
      args[k] = v === 'true' ? true : v === 'false' ? false : v;
    }
  }
  return args;
}

