export function setupGracefulShutdown(cleanup) {
  const handler = async (signal) => {
    console.log('Received', signal);
    try {
      await cleanup();
    } finally {
      process.exit(0);
    }
  };
  process.on('SIGINT', () => handler('SIGINT'));
  process.on('SIGTERM', () => handler('SIGTERM'));
}

